"use client";
import { useDialogContext } from "./context.js";
import { createContextPart } from "../create-context-part.js";
//#region src/ui/dialog/title.tsx
/** Renders the heading that labels the dialog. */
const DialogTitle = createContextPart({
	displayName: "DialogTitle",
	tag: "h2",
	useContext: useDialogContext,
	getProps: (state) => ({ id: state.titleId })
});
//#endregion
export { DialogTitle };
